#
# run-integration.sh — контейнерные пробы фундамента (testcontainers + Postgres).
#
# РАЗДЕЛИТЕЛЬ ЗДЕСЬ — `-short`, А НЕ ТЕГ СБОРКИ, и это замер, а не перенос.
# В службе, откуда взята форма этого конвейера, контейнерные пробы отделены
# `//go:build integration`, поэтому её прогон обязан нести `-tags=integration`.
# В ЭТОМ дереве файлов с тегом сборки НОЛЬ (`git ls-files '*_test.go' | xargs
# grep -lE '^//go:build' | wc -l` → 0), а разделяет прогоны сам `pgtest`: в
# коротком режиме он объявляет пропуск и контейнера не поднимает
# (`pgtest/pgtest.go`, ветка `testing.Short()`). Значит `-tags=integration`
# здесь не выбрал бы НИ ОДНОГО файла — он был бы исключением без предмета, — а
# признаком контейнерного прогона служит ОТСУТСТВИЕ `-short`.
#
# ОТБОР ИДЁТ ПО ИМПОРТУ, А НЕ ПО ПУТИ. Служба отбирает пакеты образцом пути
# (`/internal/(repo|clients|…)`), потому что там раскладка это позволяет. Здесь
# контейнерные пакеты по дереву РАЗБРОСАНЫ (`audit`, `authz`, `db`, `dropguard`,
# `migrations/common`, `operations`, `outbox` и три его подпакета, `pgtest`,
# `schemaguard`, `subscription`) и общего префикса не имеют вовсе. Образец пути
# пришлось бы выписывать перечнем — то есть завести второе место об одном
# предмете, которое разойдётся с деревом молча, как только появится новый
# контейнерный пакет. Импорт `pgtest` — признак, который дерево ПРОИЗВОДИТ само.
#
# «НЕЧЕГО ЗАПУСКАТЬ» И «НЕ СМОГ СПРОСИТЬ» — РАЗНЫЕ ИСХОДЫ. Форма
# `go list … | grep … || true` покрывает ОБА одним нулём: отбор получает пустой
# список, печатает «нечего запускать» и выходит успехом — задание зелёное, проб
# исполнено ноль. Поэтому код `go list` читается ОТДЕЛЬНО от кода `grep`, у
# которого «ничего не нашлось» — законный исход (код 1).
#
# ПУСТОЙ ОТБОР ЗДЕСЬ — ОТКАЗ, А НЕ ПРОПУСК, и это отличие от службы-образца.
# Там контейнерных пакетов могло не быть вовсе, и пропуск был защитим. Здесь их
# заведомо есть (замер на день заведения: 13 пакетов, 37 файлов проб,
# импортирующих `pgtest`), поэтому ноль отобранных означает, что сломался ОТБОР,
# а не что работы нет. Зелёное на пустом отборе — ровно тот класс, ради которого
# этот скрипт написан отдельным файлом.
#
# `-p 1` ВНУТРИ прогона: пакеты сериализуются. Под `-race` и состязание за Docker
# параллельные контейнерные пакеты голодают друг у друга ресурсы, и кейсы на
# конкуренцию (CAS/UNIQUE/EXCLUDE/SKIP LOCKED) начинают флакать — то есть давать
# красное там, где ничего не сломано.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
TIMEOUT="${INTEGRATION_TIMEOUT:-25m}"

cd "$ROOT" || exit 2

# ПОТОКИ РАЗВЕДЕНЫ. При `2>&1` диагностика `go list` попадает в тот же поток, что
# и имена пакетов, и строка ошибки становится «пакетом»: отбор считал бы её в
# перепись, а `grep` мог бы на ней и совпасть.
list_err="$(mktemp)"
log="$(mktemp)"
trap 'rm -f "$list_err" "$log"' EXIT

list_rc=0
all="$(go list ./... 2>"$list_err")" || list_rc=$?
if [ "$list_rc" -ne 0 ]; then
    echo "go list по пакетам сорвался — состав пакетов НЕ ИЗМЕРЕН." >&2
    echo "Это отказ, а не «нечего запускать»: пустой список здесь означал бы" >&2
    echo "зелёное задание с нулём выполненных проб." >&2
    tail -20 "$list_err" >&2
    exit 2
fi
if [ -z "$all" ]; then
    echo "не найдено НИ ОДНОГО пакета — обход пуст, это отказ" >&2
    exit 2
fi
total="$(printf '%s\n' "$all" | wc -l)"

# ОТБОР ПО ИМПОРТУ. `go list -f` спрашивает у самого инструмента, что пакет
# импортирует в СВОИХ пробах: `TestImports` — импорты файлов `_test.go` внутри
# пакета, `XTestImports` — импорты внешнего тестового пакета (`..._test`).
# Второе поле обязательно: без него пакет, чьи контейнерные пробы объявлены во
# внешнем тестовом пакете, выпал бы из отбора МОЛЧА.
select_err="$(mktemp)"
trap 'rm -f "$list_err" "$log" "$select_err"' EXIT
sel_rc=0
pkgs="$(go list -f '{{.ImportPath}} {{join .TestImports " "}} {{join .XTestImports " "}}' ./... 2>"$select_err" \
        | grep -E '(corelib/pgtest|testcontainers)' \
        | awk '{print $1}')" || sel_rc=$?
# grep с кодом 1 («не нашлось») законен и обрабатывается ниже; отказ самого
# `go list` — нет, и он бы дал код 2 у ПЕРВОЙ команды конвейера.
if [ "${PIPESTATUS[0]:-0}" -ne 0 ] && [ -s "$select_err" ]; then
    echo "отбор контейнерных пакетов сорвался — состав НЕ ИЗМЕРЕН." >&2
    tail -20 "$select_err" >&2
    exit 2
fi
if [ -z "$pkgs" ]; then
    echo "ОТКАЗ: контейнерных пакетов не отобрано НИ ОДНОГО (осмотрено: $total)." >&2
    echo "В этом дереве они заведомо есть — значит сломался ОТБОР, а не работа." >&2
    echo "Признак отбора: импорт corelib/pgtest либо testcontainers в пробах пакета." >&2
    exit 2
fi
selected="$(printf '%s\n' "$pkgs" | wc -l)"

echo "=== ОТБОР ==="
echo "осмотрено пакетов : $total"
echo "отобрано          : $selected  (признак: импорт corelib/pgtest | testcontainers)"
printf '%s\n' "$pkgs" | sed 's/^/                    /'
echo ""

# КОД ВОЗВРАТА БЕРЁТСЯ У `go test`, И ЭТО НЕ ПЕДАНТИЗМ — ОТ НЕГО ЗАВИСИТ ВЕРДИКТ.
# Труба отдаёт код ПРАВОЙ команды, то есть `tee`, то есть ноль почти всегда;
# `xargs` на упавшей команде возвращает СВОЙ код 123, а не код `go test`.
# Поэтому: без `xargs` (пути пакетов Go пробелов не содержат) и `PIPESTATUS[0]`
# снимается СРАЗУ после трубы, до любой другой команды — иначе его затрёт даже
# присваивание.
#
# `-short` ЗДЕСЬ НЕТ НАМЕРЕННО: он и есть выключатель контейнеров.
# shellcheck disable=SC2086
go test -race -count=1 -timeout "$TIMEOUT" -p 1 $pkgs 2>&1 | tee "$log"
rc="${PIPESTATUS[0]}"

out=0
"$ROOT/.github/scripts/classify-integration-outcome.sh" "$rc" "$log" || out=$?
exit "$out"
